import{_ as e,c as t,o as l,ag as i}from"./chunks/framework.B1jFR3yW.js";const c=JSON.parse('{"title":"大文件上传","description":"","frontmatter":{},"headers":[],"relativePath":"随记/代码库/002-大文件上传.md","filePath":"随记/代码库/002-大文件上传.md"}'),r={name:"随记/代码库/002-大文件上传.md"};function o(n,a,_,p,s,d){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="大文件上传" tabindex="-1">大文件上传 <a class="header-anchor" href="#大文件上传" aria-label="Permalink to &quot;大文件上传&quot;">​</a></h1><p>文件上传其实就是把二进制流传输给后端，后端在做处理。当文件特别大的是时候，会导致传输时间过程，过长的时间就会产生很多不可控性。</p><p>解决方案：文件切片。</p><h2 id="一、切片上传" tabindex="-1">一、切片上传 <a class="header-anchor" href="#一、切片上传" aria-label="Permalink to &quot;一、切片上传&quot;">​</a></h2><p>原理：将文件拆分为多个小文件，分别传给后端，传完之后后端再合并。</p><p>切片拆分：按指定长度把二进制流拆了。</p><h2 id="二、文件秒传" tabindex="-1">二、文件秒传 <a class="header-anchor" href="#二、文件秒传" aria-label="Permalink to &quot;二、文件秒传&quot;">​</a></h2><p>文件秒传，其实指的是文件不用传。如果某一个文件，在之前已经上传成功过，再次上传时，就可以直接提示用户“上传成功”。</p><p>原理：上传前将文件名或指定规则唯一标识传给后端，判断一下是否传过。</p><h2 id="三、断点续传" tabindex="-1">三、断点续传 <a class="header-anchor" href="#三、断点续传" aria-label="Permalink to &quot;三、断点续传&quot;">​</a></h2><p>两种场景：</p><ol><li>用户点击暂停，终止文件上传；再次点击上传时，继续上传剩下部分</li><li>由外部原因造成的上传失败；后续重传可接着上次传输进度继续上传。</li></ol><p>两种场景的处理方式其实和“文件秒传”是一样的，工作流程大致如下：</p><ol><li>文件上传（续传）前，将文件名发送到后端，来判断当前文件是否有上传成功过的部分切片文件；</li><li>如果有上传过部分切片，后端将上传成功的切片文件名返回给前端；</li><li>前端从所有切片中，将已经上传成功的切片筛选出来，再将剩下未上传成功的切片重新发送给后端；</li><li>后端将所有切片合并，完成整个文件的上传；</li></ol>',14)])])}const m=e(r,[["render",o]]);export{c as __pageData,m as default};
